#!/usr/bin/env node
/**
 * Check candidate YouTube ids before they are allowed near the app.
 *
 * A guessed id is worse than no id: the card silently plays the wrong video,
 * or a dead player. Two gates, and an id must pass both:
 *
 *   1. oEmbed  — the id exists, and prints its real title and channel so a
 *                human can confirm the video actually matches the event.
 *   2. embed   — the video is *playable in an iframe*. This is not implied by
 *                gate 1: a rights holder can leave a video public while
 *                forbidding embedding, and YouTube then reports it only to the
 *                player, as IFrame API error 101/150. Sports and agency
 *                footage do this constantly.
 *
 * Gate 2 needs a real player, because nothing server-side tells the truth
 * about it: the watch page's `playableInEmbed` reads true for videos that are
 * in fact blocked, and the innertube embedded-player endpoint rejects
 * unauthenticated probes outright. So it loads the ids in gsd-browser and
 * listens for onReady vs onError. Skip it with --no-embed-check only if the
 * browser is unavailable, and expect some players to ship dead.
 *
 *   node scripts/verify-youtube.mjs candidates.json         # report only
 *   node scripts/verify-youtube.mjs candidates.json --write # merge passing ids
 *   node scripts/verify-youtube.mjs --audit                 # re-check shipped ids
 *
 * candidates.json: { "<event id>": "<youtube id>", ... }
 *
 * --write MERGES into youtube-verified.json, so a run covering a handful of
 * events cannot silently drop the rest, and a repair can replace one entry.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { createServer } from 'node:http';
import { execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.<COMPANY_NAME_REDACTED>.url));
const OUT = resolve(here, '../src/data/youtube-verified.json');

const [, , ...argv] = process.argv;
const flags = argv.filter((a) => a.startsWith('--'));
const candidatesPath = argv.find((a) => !a.startsWith('--'));
const auditMode = flags.includes('--audit');

if (!candidatesPath && !auditMode) {
  console.error('usage: node scripts/verify-youtube.mjs <candidates.json> [--write] [--no-embed-check]');
  console.error('       node scripts/verify-youtube.mjs --audit');
  process.exit(2);
}

const candidates = auditMode
  ? JSON.parse(await readFile(OUT, 'utf8'))
  : JSON.parse(await readFile(resolve(process.cwd(), candidatesPath), 'utf8'));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* ---------------------------------------------------------------- gate 1 */

async function probe(videoId) {
  const url = `https://www.youtube.com/oembed?url=${
    encodeURIComponent(`https://www.youtube.com/watch?v=${videoId}`)}&format=json`;
  try {
    const res = await fetch(url);
    if (!res.ok) return { ok: false, reason: `HTTP ${res.status}` };
    const json = await res.json();
    return { ok: true, title: json.title, author: json.author_name };
  } catch (err) {
    return { ok: false, reason: err.message };
  }
}

const results = [];
for (const [eventId, videoId] of Object.entries(candidates)) {
  const result = await probe(videoId);
  results.push({ eventId, videoId, ...result });
  console.log(
    result.ok
      ? `LIVE  ${eventId.padEnd(26)} ${videoId}  "${result.title}" — ${result.author}`
      : `DEAD  ${eventId.padEnd(26)} ${videoId}  (${result.reason})`,
  );
}

const live = results.filter((r) => r.ok);
console.log(`\n${live.length}/${results.length} ids resolve.`);
console.log('A resolving id is not yet a correct one — read the titles above and');
console.log('drop any that do not match the event before writing.');

/* ---------------------------------------------------------------- gate 2 */

function harness(entries) {
  const map = Object.fromEntries(entries.map((e) => [e.eventId, e.videoId]));
  return `<!doctype html><html><head><<COMPANY_NAME_REDACTED> charset="utf-8"><title>embed gate</title></head>
<body><div id="hosts"></div><script>
const CAND = ${JSON.stringify(map)};
window.__results = {};
const hosts = document.getElementById('hosts');
Object.keys(CAND).forEach((ev, i) => {
  const d = document.createElement('div'); d.id = 'p' + i; hosts.appendChild(d);
});
window.onYouTubeIframeAPIReady = function () {
  Object.entries(CAND).forEach(([ev, vid], i) => {
    new YT.Player('p' + i, { videoId: vid, width: 120, height: 80, events: {
      onReady: () => { if (!window.__results[ev]) window.__results[ev] = { vid, state: 'ready' }; },
      onError: (e) => { window.__results[ev] = { vid, state: 'error', code: e.data }; },
    } });
  });
};
const t = document.createElement('script');
t.src = 'https://www.youtube.com/iframe_api';
document.head.appendChild(t);
</script></body></html>`;
}

function gsd(args) {
  return new Promise((ok, fail) => {
    execFile('gsd-browser', args, { timeout: 120000 }, (err, stdout, stderr) => {
      if (err) return fail(new Error(`${err.message} ${stderr || ''}`));
      ok(stdout.trim());
    });
  });
}

/** Error codes the IFrame API uses for "this will never play here". */
const EMBED_BLOCKED = new Set([101, 150]);

/**
 * Players per page. Well below what kills the tab: past roughly 80 the page
 * stops reporting altogether — every id comes back with no verdict, which
 * reads exactly like "everything is blocked" and is completely wrong. Auditing
 * the whole file is the case that hits this, so the gate always batches.
 */
const CHUNK = 20;

async function embedGate(entries) {
  const seen = {};
  for (let i = 0; i < entries.length; i += CHUNK) {
    const batch = entries.slice(i, i + CHUNK);
    if (entries.length > CHUNK) {
      console.log(`  …batch ${i / CHUNK + 1} of ${Math.ceil(entries.length / CHUNK)} (${batch.length} ids)`);
    }
    // A batch that reports nothing at all is the browser being unwell, not 20
    // blocked videos — a wedged tab looks identical to unanimous rejection.
    // Retry once on a fresh page before believing a shutout.
    let got = await embedBatch(batch);
    if (Object.keys(got).length === 0) {
      console.log('    (no verdicts — retrying batch on a fresh page)');
      got = await embedBatch(batch);
    }
    Object.assign(seen, got);
  }
  return seen;
}

async function embedBatch(entries) {
  const html = harness(entries);
  const server = createServer((_req, res) => {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(html);
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const { port } = server.address();
  try {
    await gsd(['navigate', `http://localhost:${port}/`]);
    let seen = {};
    for (let i = 0; i < 20; i += 1) {
      await sleep(3000);
      const raw = await gsd(['eval', 'JSON.stringify(window.__results||{})']);
      const line = raw.split('\n').map((l) => l.trim()).filter(Boolean).pop() || '{}';
      try { seen = JSON.parse(line); } catch { /* player still booting */ }
      if (Object.keys(seen).length >= entries.length) break;
    }
    return seen;
  } finally {
    server.close();
  }
}

const blocked = new Set();
const inconclusive = new Set();
if (live.length && !flags.includes('--no-embed-check')) {
  console.log('\nEmbed gate — loading each id in a real player (gsd-browser):');
  try {
    const seen = await embedGate(live);
    for (const { eventId, videoId } of live) {
      const r = seen[eventId];
      if (!r) {
        // NOT the same as blocked. Reporting it as blocked would invite
        // "repairing" videos that are perfectly fine.
        console.log(`  ????  ${eventId.padEnd(26)} ${videoId}  no verdict — inconclusive, re-run`);
        inconclusive.add(eventId);
      } else if (r.state === 'ready') {
        console.log(`  PLAYS ${eventId.padEnd(26)} ${videoId}`);
      } else {
        const why = EMBED_BLOCKED.has(r.code) ? 'embedding disabled by owner' : 'player error';
        console.log(`  BLOCK ${eventId.padEnd(26)} ${videoId}  code ${r.code} (${why})`);
        blocked.add(eventId);
      }
    }
    const played = live.length - blocked.size - inconclusive.size;
    console.log(`\n${played}/${live.length} resolving ids actually play when embedded.`);
    if (inconclusive.size) {
      console.log(`${inconclusive.size} gave no verdict — unproven either way, not a failure. Re-run to settle them.`);
    }
  } catch (err) {
    console.error(`\nEmbed gate could not run: ${err.message}`);
    console.error('Start the browser (gsd-browser daemon start) or pass --no-embed-check.');
    process.exit(1);
  }
} else if (flags.includes('--no-embed-check')) {
  console.log('\nEmbed gate SKIPPED — ids may resolve and still refuse to play in the app.');
}

const passing = live.filter((r) => !blocked.has(r.eventId) && !inconclusive.has(r.eventId));

if (auditMode) {
  console.log(`\nAudit: ${passing.length}/${results.length} shipped ids proven healthy.`);
  const broken = results.filter((r) => !r.ok || blocked.has(r.eventId));
  if (broken.length) {
    console.log('Needs replacing:');
    for (const b of broken) console.log(`  ${b.eventId}  ${b.videoId}`);
    process.exitCode = 1;
  } else {
    console.log('Nothing needs replacing.');
  }
  if (inconclusive.size) {
    console.log(`Unproven this run (re-run to settle): ${[...inconclusive].join(', ')}`);
  }
} else if (flags.includes('--write')) {
  let existing = {};
  try { existing = JSON.parse(await readFile(OUT, 'utf8')); } catch { /* first run */ }
  const additions = Object.fromEntries(passing.map((r) => [r.eventId, r.videoId]));
  const merged = Object.fromEntries(
    Object.entries({ ...existing, ...additions }).sort(([a], [b]) => a.localeCompare(b)),
  );
  await writeFile(OUT, `${JSON.stringify(merged, null, 2)}\n`);
  const changed = Object.keys(additions).filter((k) => existing[k] !== additions[k]).length;
  console.log(`\nMerged ${changed} id(s) into ${OUT} — ${Object.keys(merged).length} total.`);
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import TopBar from '@/components/TopBar';
import BottomBar from '@/components/BottomBar';
import Rail from '@/components/Rail';
import FocusCursor from '@/components/FocusCursor';
import EventDetail from '@/components/EventDetail';
import SettingsPanel from '@/components/SettingsPanel';
import Drawer from '@/components/Drawer';
import { useTimelineScroll } from '@/hooks/useTimelineScroll';
import { useTimeline } from '@/state/timeline-store';
import { ALL_CATEGORY_IDS, type CategoryId } from '@/config/categories';
import { MIN_WEIGHT_BY_ZOOM } from '@/config/timeline';
import { assignLanes } from '@/utils/lanes';
import { addYears } from '@/utils/time';
import type { PlacedEvent } from '@/data/types';

export default function App() {
  const { profile, timeline } = useTimeline();

  // Start on today: the cursor then has life on one side and the mirrored
  // pre-history on the other, which is the comparison the app exists to make.
  const scroll = useTimelineScroll({
    maxSpan: timeline.maxSpan,
    initialOffset: timeline.yearsLived,
  });
  const { offset, pxPerYear, dragging, glideTo } = scroll;

  const [active, setActive] = useState<Set<CategoryId>>(() => new Set(ALL_CATEGORY_IDS));
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // The setup card opens itself the first time, because a placeholder birth
  // date silently produces a plausible-looking but wrong timeline.
  const [settingsOpen, setSettingsOpen] = useState(() => !profile.configured);
  // Narrow screens park the filters and zoom controls behind a hamburger; on a
  // wide screen the drawer is never displayed and this stays false.
  const [drawerOpen, setDrawerOpen] = useState(false);

  const toggleCategory = useCallback((id: CategoryId) => {
    setActive((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id); else next.add(id);
      // Never leave the user staring at an empty timeline.
      return next.size === 0 ? new Set(ALL_CATEGORY_IDS) : next;
    });
  }, []);

  // Changing the birth date rebuilds both rails, so a selection made against
  // the old hinge may no longer exist.
  useEffect(() => {
    setSelectedId((current) =>
      (current && timeline.all.some((e) => e.id === current) ? current : null));
  }, [timeline]);

  // Moving the inflection point invalidates where the cursor was standing: an
  // offset of "51 years from birth" means a different moment once birth moves.
  // Re-anchor on today, which is where the app opens. Skipped on first mount,
  // which already starts there.
  const birthKey = timeline.birth.getTime();
  const firstAnchor = useRef(true);
  useEffect(() => {
    if (firstAnchor.current) { firstAnchor.current = false; return; }
    glideTo(timeline.yearsLived);
  }, [birthKey, glideTo, timeline.yearsLived]);

  const selected: PlacedEvent | null = useMemo(
    () => timeline.all.find((e) => e.id === selectedId) ?? null,
    [timeline, selectedId],
  );

  /** Bring an event under the cursor and open its zoomed panel. */
  const openEvent = useCallback((event: PlacedEvent) => {
    setSelectedId(event.id);
    glideTo(event.yearsFromBirth);
  }, [glideTo]);

  const onCardSelect = useCallback((years: number, id: string) => {
    setSelectedId((current) => (current === id ? null : id));
    glideTo(years);
  }, [glideTo]);

  // Zoom and lane packing together decide how many events actually fit. Report
  // the real number rather than a vague label, so it is clear that zooming in
  // reveals events instead of merely enlarging the ones already on screen.
  const placed = useMemo(() => {
    const minWeight = MIN_WEIGHT_BY_ZOOM[scroll.zoomIndex] ?? 1;
    let shown = 0;
    let total = 0;

    for (const rail of ['forward', 'mirror'] as const) {
      const inScope = timeline.events(rail).filter((e) => active.has(e.category));
      total += inScope.length;
      const admitted = inScope.filter(
        (e) => e.weight >= minWeight || e.category === 'personal');
      shown += assignLanes(admitted, pxPerYear).filter((lane) => lane !== null).length;
    }
    return { shown, total };
  }, [timeline, scroll.zoomIndex, pxPerYear, active]);

  // The two dates the cursor is reading, one on each rail.
  const forwardDate = useMemo(() => addYears(timeline.birth, offset), [timeline.birth, offset]);
  const mirrorDate = useMemo(() => addYears(timeline.birth, -offset), [timeline.birth, offset]);

  return (
    <div className="app">
      <TopBar
        offset={offset}
        forwardDate={forwardDate}
        mirrorDate={mirrorDate}
        onSearchPick={openEvent}
        onOpenSettings={() => setSettingsOpen(true)}
        drawerOpen={drawerOpen}
        onToggleDrawer={() => setDrawerOpen((open) => !open)}
      />

      <main
        className={`stage${dragging ? ' stage--dragging' : ''}`}
        onWheel={scroll.handlers.onWheel}
        onPointerDown={scroll.handlers.onPointerDown}
        role="application"
        aria-label="Mirrored timeline. Drag or scroll to travel; arrow keys step by year."
      >
        <Rail
          rail="forward"
          offset={offset}
          pxPerYear={pxPerYear}
          zoomIndex={scroll.zoomIndex}
          activeCategories={active}
          selectedId={selectedId}
          onSelect={onCardSelect}
        />

        <FocusCursor offset={offset} forwardDate={forwardDate} mirrorDate={mirrorDate} />

        <Rail
          rail="mirror"
          offset={offset}
          pxPerYear={pxPerYear}
          zoomIndex={scroll.zoomIndex}
          activeCategories={active}
          selectedId={selectedId}
          onSelect={onCardSelect}
        />

        {selected && (
          <EventDetail event={selected} onClose={() => setSelectedId(null)} />
        )}
      </main>

      <BottomBar
        offset={offset}
        maxSpan={timeline.maxSpan}
        yearsLived={timeline.yearsLived}
        zoomIndex={scroll.zoomIndex}
        placed={placed}
        onZoom={scroll.setZoomIndex}
        onScrub={glideTo}
        activeCategories={active}
        onToggleCategory={toggleCategory}
      />

      <Drawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        activeCategories={active}
        onToggleCategory={toggleCategory}
        zoomIndex={scroll.zoomIndex}
        yearsLived={timeline.yearsLived}
        placed={placed}
        onZoom={scroll.setZoomIndex}
        onScrub={glideTo}
        onOpenSettings={() => setSettingsOpen(true)}
      />

      {settingsOpen && (
        <SettingsPanel onClose={() => setSettingsOpen(false)} firstRun={!profile.configured} />
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import EventCard from './EventCard';
import AxisRuler from './AxisRuler';
import { useTimeline } from '@/state/timeline-store';
import type { RailId } from '@/data/types';
import type { CategoryId } from '@/config/categories';
import { assignLanes } from '@/utils/lanes';
import {
  CULL_DISTANCE, LANES_PER_RAIL, MIN_LANE_HEIGHT, MIN_WEIGHT_BY_ZOOM, PERSPECTIVE,
} from '@/config/timeline';

interface Props {
  rail: RailId;
  offset: number;
  pxPerYear: number;
  zoomIndex: number;
  activeCategories: Set<CategoryId>;
  selectedId: string | null;
  onSelect: (years: number, id: string) => void;
}

const RAIL_COPY: Record<RailId, { title: string; hint: string }> = {
  forward: { title: 'Your life', hint: 'birth → onward' },
  mirror: { title: 'Mirrored time', hint: 'birth → backward' },
};

/**
 * One time axis. Both rails are identical in construction — they differ only in
 * which half of the dataset they draw and which way they read the calendar.
 */
export default function Rail({
  rail, offset, pxPerYear, zoomIndex, activeCategories, selectedId, onSelect,
}: Props) {
  const { timeline } = useTimeline();
  const minWeight = MIN_WEIGHT_BY_ZOOM[zoomIndex] ?? 1;

  // Only the events this zoom level admits take part in lane packing, so the
  // survivors spread into the space the dropped ones would have taken.
  const events = useMemo(
    () => timeline.events(rail)
      .filter((e) => e.weight >= minWeight || e.category === 'personal'),
    [timeline, rail, minWeight],
  );

  // Lane height is derived from the rail's real height rather than fixed, so
  // the outermost lane always fits on screen instead of clipping on short
  // viewports. Measured, not assumed.
  const sceneRef = useRef<HTMLDivElement>(null);
  const [sceneHeight, setSceneHeight] = useState(0);

  useEffect(() => {
    const node = sceneRef.current;
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => {
      setSceneHeight(entry.contentRect.height);
    });
    observer.observe(node);
    setSceneHeight(node.clientHeight);
    return () => observer.disconnect();
  }, []);

  const laneHeight = Math.max(
    MIN_LANE_HEIGHT,
    (sceneHeight || MIN_LANE_HEIGHT * LANES_PER_RAIL) / LANES_PER_RAIL,
  );

  // Lane packing depends only on zoom, so it survives every scroll frame.
  const lanes = useMemo(() => assignLanes(events, pxPerYear), [events, pxPerYear]);

  // Viewport culling: only cards near the cursor are in the DOM at all.
  const visible = useMemo(() => {
    const out: { event: (typeof events)[number]; dx: number; lane: number }[] = [];
    for (let i = 0; i < events.length; i++) {
      const event = events[i];
      if (!activeCategories.has(event.category)) continue;
      const lane = lanes[i];
      if (lane === null) continue; // no room in any lane at this zoom
      const dx = (event.yearsFromBirth - offset) * pxPerYear;
      if (Math.abs(dx) > CULL_DISTANCE) continue;
      out.push({ event, dx, lane });
    }
    return out;
  }, [events, lanes, offset, pxPerYear, activeCategories]);

  const copy = RAIL_COPY[rail];

  return (
    <section className={`rail rail--${rail}`} aria-label={`${copy.title} axis`}>
      <div className="rail__scene" ref={sceneRef} style={{ perspective: `${PERSPECTIVE}px` }}>
        <div className="rail__cards">
          {visible.map(({ event, dx, lane }) => (
            <EventCard
              key={event.id}
              event={event}
              dx={dx}
              lane={lane}
              rail={rail}
              laneHeight={laneHeight}
              selected={selectedId === event.id}
              onSelect={onSelect}
            />
          ))}
        </div>
      </div>

      <AxisRuler rail={rail} offset={offset} pxPerYear={pxPerYear} />

      <div className="rail__legend">
        <span className="rail__legend-title">{copy.title}</span>
        <span className="rail__legend-hint">{copy.hint}</span>
      </div>
    </section>
  );
}
=================== lanes.ts
import { CARD_GAP, CARD_WIDTH, LANES_PER_RAIL } from '@/config/timeline';

interface Placeable {
  yearsFromBirth: number;
  weight: number;
}

/**
 * Packs events into horizontal lanes so that neighbours in time do not overlap.
 *
 * Lanes are assigned in *timeline* space (years), not screen space, so the
 * assignment only has to be recomputed when the zoom changes — never while
 * scrolling, which keeps cards from reshuffling under the cursor.
 *
 * Heavier events are placed first and so claim the lanes nearest the axis,
 * where the eye lands. When every lane is already taken at that point in time,
 * the event is *dropped* rather than stacked on top of a neighbour: a dense
 * decade holds far more events than three lanes can show, and an unreadable
 * pile of half-covered titles is worse than an honest omission. Because the
 * sort is by weight, what falls out is always the least significant event, and
 * zooming in widens the gap and brings it back.
 *
 * Returns one entry per input event: its lane, or null if it was dropped.
 */
export function assignLanes<T extends Placeable>(
  events: T[],
  pxPerYear: number,
): (number | null)[] {
  const minGapYears = (CARD_WIDTH + CARD_GAP) / pxPerYear;

  const order = events
    .map((event, index) => ({ event, index }))
    .sort((a, b) =>
      b.event.weight - a.event.weight ||
      a.event.yearsFromBirth - b.event.yearsFromBirth);

  // Per lane, the centres already claimed on the timeline.
  const claimed: number[][] = Array.from({ length: LANES_PER_RAIL }, () => []);
  const lanes = new Array<number | null>(events.length).fill(null);

  for (const { event, index } of order) {
    const at = event.yearsFromBirth;

    for (let lane = 0; lane < LANES_PER_RAIL; lane++) {
      const clear = claimed[lane].every((taken) => Math.abs(taken - at) >= minGapYears);
      if (clear) {
        claimed[lane].push(at);
        lanes[index] = lane;
        break;
      }
    }
  }

  return lanes;
}
=================== timeline.ts
/**
 * Geometry and motion constants for the two mirrored rails.
 *
 * The whole visualisation is driven by one scalar: `offset`, measured in years
 * from the birth date. Both rails read it the same way —
 *
 *   forward rail shows  birth + offset
 *   mirror  rail shows  birth − offset
 *
 * so an event's distance from birth, not its calendar date, is its coordinate.
 * That is what makes the two axes mirror each other.
 */

/** Horizontal pixels per year at each zoom step. Index into ZOOM_LEVELS. */
export const ZOOM_LEVELS = [18, 32, 56, 96, 168, 290] as const;
export const DEFAULT_ZOOM_INDEX = 2;

/**
 * Level of detail, parallel to ZOOM_LEVELS: the lowest event weight drawn at
 * each zoom step. A busy decade holds far more events than three lanes can
 * show without overlapping, so zooming out drops the minor ones rather than
 * stacking unreadable cards. Zooming back in returns them.
 */
export const MIN_WEIGHT_BY_ZOOM = [3, 2, 1, 1, 1, 1] as const;

/** Card footprint used for lane packing and culling. */
export const CARD_WIDTH = 236;
export const CARD_GAP = 14;
export const LANES_PER_RAIL = 3;
/** Used only until the rail has been measured, and as a lower bound. */
export const MIN_LANE_HEIGHT = 120;
/** A lane this tall has room for a thumbnail as well as text. */
export const LANE_HEIGHT_FOR_IMAGE = 230;

/**
 * Depth falls off asymptotically rather than linearly: a linear ramp sends far
 * cards racing to the vanishing point and piles them on top of each other.
 * z(d) = -MAX_DEPTH * d / (d + DEPTH_HALF)  — half of max depth at DEPTH_HALF px.
 */
export const MAX_DEPTH = 760;
export const DEPTH_HALF = 900;
export const PERSPECTIVE = 1500;

/** Cards yaw toward the focus cursor, like a rack of slides seen edge-on. */
export const MAX_YAW_DEG = 46;
export const YAW_FALLOFF = 12;

/** Fade and defocus: "further out of focus is increasingly faded". */
export const FADE_START = 180;
export const FADE_RANGE = 1350;
export const MIN_OPACITY = 0.05;
export const MAX_BLUR = 4.2;

/** Beyond this screen distance a card is not rendered at all (viewport culling). */
export const CULL_DISTANCE = 1900;

/** A card this close to the cursor is "in focus" — full size, video playable. */
export const FOCUS_RADIUS = 90;

/** Scroll feel. */
export const WHEEL_YEARS_PER_PIXEL = 0.0016;
export const DRAG_MULTIPLIER = 1;
export const FRICTION = 0.92;
export const MIN_VELOCITY = 0.00015;
/** Easing per frame when animating to a clicked card. */
export const GLIDE_EASE = 0.14;

/** How far past the ends of the data the rails may be scrolled. */
export const OVERSCROLL_YEARS = 3;

import { CATEGORIES } from '@/config/categories';
import { CARD_WIDTH, FOCUS_RADIUS, LANE_HEIGHT_FOR_IMAGE } from '@/config/timeline';
import type { PlacedEvent, RailId } from '@/data/types';
import { useTimeline } from '@/state/timeline-store';
import { depthStyleFor } from '@/utils/depth';
import { formatAge, formatEventDate } from '@/utils/time';
import { useWikiSummary } from '@/hooks/useWikiSummary';

interface Props {
  event: PlacedEvent;
  /** Signed pixels from the focus cursor. */
  dx: number;
  lane: number;
  rail: RailId;
  /** Measured height of one lane — the card's height budget. */
  laneHeight: number;
  selected: boolean;
  onSelect: (years: number, id: string) => void;
}

/** Description and enrichment appear only once a card is readable. */
const DETAIL_DEFOCUS = 0.30;
const ENRICH_DEFOCUS = 0.10;

/**
 * A tile on the rail. Clicking it glides the timeline to bring it under the
 * cursor and opens the zoomed detail panel, which is where the full text,
 * links and video live — a card on the rail is too small to hold a usable
 * player, and every card is a moving target while the rails scroll.
 */
export default function EventCard({
  event, dx, lane, rail, laneHeight, selected, onSelect,
}: Props) {
  const { timeline } = useTimeline();
  const precision = timeline.precision[event.id];

  const { scale, projectedDx, yawDeg, opacity, blurPx, defocus } = depthStyleFor(dx);
  const focused = Math.abs(dx) <= FOCUS_RADIUS;
  const category = CATEGORIES[event.category];

  const wiki = useWikiSummary(event.media.wiki, defocus < ENRICH_DEFOCUS);
  const showDetail = defocus < DETAIL_DEFOCUS;
  const showImage = wiki?.thumbnail && defocus < ENRICH_DEFOCUS && laneHeight >= LANE_HEIGHT_FOR_IMAGE;

  const dateLabel = formatEventDate(event.date, precision);
  const far = defocus > 0.8;

  const classes = [
    'card',
    `card--${event.category}`,
    focused ? 'card--focused' : '',
    selected ? 'card--selected' : '',
    event.category === 'personal' ? 'card--personal' : '',
    `card--weight-${event.weight}`,
  ].filter(Boolean).join(' ');

  return (
    <article
      className={classes}
      style={{
        // left:50% puts the card's anchor on the cursor; the -50% centres it
        // (scale is about the centre, so this stays correct at any scale),
        // projectedDx slides it along the rail and scale supplies the depth.
        // Deliberately no translateZ — see utils/depth.ts.
        transform: `translateX(calc(-50% + ${projectedDx.toFixed(1)}px)) scale(${scale.toFixed(4)}) rotateY(${yawDeg.toFixed(2)}deg)`,
        [rail === 'forward' ? 'bottom' : 'top']: `${lane * laneHeight}px`,
        opacity,
        filter: blurPx > 0.05 ? `blur(${blurPx}px)` : undefined,
        width: `${CARD_WIDTH}px`,
        maxHeight: `${laneHeight - 8}px`,
        // Near cards must paint over far ones regardless of DOM order.
        zIndex: Math.round(1000 - Math.abs(dx)),
        ['--cat-hue' as string]: category.hue,
      }}
      // Far cards are decorative at best and must not be tab stops or read out.
      aria-hidden={far ? true : undefined}
    >
      <button
        type="button"
        className="card__hit"
        onClick={() => onSelect(event.yearsFromBirth, event.id)}
        tabIndex={far ? -1 : 0}
        aria-label={`${event.title}. ${dateLabel}. ${category.label}. Open details.`}
      >
        <header className="card__head">
          {/* Glyph *and* name: the palette's CVD margin relies on this label. */}
          <span className="card__cat">
            <span className="card__glyph" aria-hidden="true">{category.glyph}</span>
            {category.label}
          </span>
          <time className="card__date" dateTime={event.date.toISOString().slice(0, 10)}>
            {dateLabel}
          </time>
        </header>

        {showImage && (
          <div className="card__image">
            <img src={wiki.thumbnail} alt="" loading="lazy" decoding="async" />
          </div>
        )}

        <h3 className="card__title">{event.title}</h3>

        {showDetail && event.description && (
          <p className="card__body">{event.description}</p>
        )}

        {showDetail && (
          <footer className="card__foot">
            <span className="card__age">
              {rail === 'forward'
                ? (event.yearsFromBirth < 0.02
                  ? 'the day you were born'
                  : `you were ${formatAge(event.yearsFromBirth)}`)
                : `${formatAge(event.yearsFromBirth)} before you`}
            </span>

            {/*
              Every card opens into the zoomed panel, but nothing said so —
              which made the whole feature invisible. These badges advertise
              what is behind each one, and the "expand" hint on hover says
              plainly that the card is a door.
            */}
            <span className="card__badges">
              {event.media.youtubeId && (
                <span className="card__badge card__badge--video" title="Plays a video here">
                  ▶ video
                </span>
              )}
              {event.media.wiki && (
                <span className="card__badge" title="Background from Wikipedia">
                  Wikipedia
                </span>
              )}
              {/*
                Always visible, never hover-only: a hover hint does not exist on
                a touch screen and does nothing for someone scanning the rails.
                This is the affordance that says the card is a door.
              */}
              <span className="card__badge card__badge--open" title="Click to expand">
                ⤢
              </span>
            </span>
          </footer>
        )}

        <span className="card__expand" aria-hidden="true">Click to expand</span>
      </button>
    </article>
  );
}

